-- Store editable Home Hero calls to action without changing other page sections.

SET @has_hero_buttons=(SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='site_page_sections' AND COLUMN_NAME='buttons_json');
SET @sql=IF(@has_hero_buttons=0,'ALTER TABLE site_page_sections ADD COLUMN buttons_json MEDIUMTEXT NULL AFTER content_html','SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

UPDATE site_page_sections s JOIN site_pages p ON p.site_page_id=s.site_page_id
SET s.buttons_json='[{"label":"See How It Works","url":"?view=how_it_works","member_url":"","target":"_self","visible":true,"text_color":"#1C242B","text_hover_color":"#1C242B","background_color":"#F4EEE2","background_hover_color":"#FFFFFF","background_end_color":"#F4EEE2","background_hover_end_color":"#FFFFFF","border_color":"#1C242B","border_hover_color":"#6B2938","border_width":1,"border_radius":6,"padding_y":13,"padding_x":20,"font_size":"","font_weight":"","text_transform":"","hover_effect":"LIFT","background_type":"SOLID","width":"AUTO","min_width":150,"border_style":"SOLID","shadow":"SOFT"},{"label":"Join A Story","url":"?view=login","member_url":"./","target":"_self","visible":true,"text_color":"#1C242B","text_hover_color":"#1C242B","background_color":"#B58E46","background_hover_color":"#D5B56B","background_end_color":"#F4EEE2","background_hover_end_color":"#FFFFFF","border_color":"#B58E46","border_hover_color":"#D5B56B","border_width":1,"border_radius":6,"padding_y":13,"padding_x":20,"font_size":"","font_weight":"","text_transform":"","hover_effect":"LIFT","background_type":"SOLID","width":"AUTO","min_width":150,"border_style":"SOLID","shadow":"SOFT"},{"label":"Host A Game","url":"?view=register","member_url":"./","target":"_self","visible":true,"text_color":"#1C242B","text_hover_color":"#1C242B","background_color":"#F4EEE2","background_hover_color":"#FFFFFF","background_end_color":"#F4EEE2","background_hover_end_color":"#FFFFFF","border_color":"#1C242B","border_hover_color":"#6B2938","border_width":1,"border_radius":6,"padding_y":13,"padding_x":20,"font_size":"","font_weight":"","text_transform":"","hover_effect":"LIFT","background_type":"SOLID","width":"AUTO","min_width":150,"border_style":"SOLID","shadow":"SOFT"}]'
WHERE p.page_code='HOME' AND s.section_code='HERO' AND (s.buttons_json IS NULL OR s.buttons_json='');

INSERT IGNORE INTO schema_migrations(migration) VALUES('095_home_hero_buttons.sql');
